<?php
namespace Database\Seeders;use App\Models\{Account,Department,JobPosition,LeaveType,PayrollComponent,Property,StaffShift};use Illuminate\Database\Seeder;class HotelHrSeeder extends Seeder{public function run():void{foreach(Property::all() as $p){$deps=['FRO'=>'Front Office','HOU'=>'Housekeeping','FNB'=>'Food & Beverage','KIT'=>'Kitchen','FIN'=>'Finance','HR'=>'Human Resources','ENG'=>'Engineering & Maintenance','SEC'=>'Security'];foreach($deps as $code=>$name)Department::firstOrCreate(['property_id'=>$p->id,'code'=>$code],['name'=>$name]);foreach([['Receptionist','REC','FRO'],['Housekeeper','HSK','HOU'],['Waiter','WTR','FNB'],['Chef','CHF','KIT'],['Accountant','ACC','FIN'],['HR Officer','HRO','HR'],['Maintenance Technician','MNT','ENG']] as [$title,$code,$dep])JobPosition::firstOrCreate(['property_id'=>$p->id,'code'=>$code],['title'=>$title,'department_id'=>Department::where('property_id',$p->id)->where('code',$dep)->value('id')]);foreach([['Morning','07:00','15:00'],['Evening','15:00','23:00'],['Night','23:00','07:00']] as [$name,$start,$end])StaffShift::firstOrCreate(['property_id'=>$p->id,'name'=>$name],['starts_at'=>$start,'ends_at'=>$end,'is_overnight'=>$end<=$start]);foreach([['Annual Leave',21,true],['Sick Leave',0,true],['Maternity Leave',0,true],['Paternity Leave',0,true],['Unpaid Leave',0,false]] as [$name,$days,$paid])LeaveType::firstOrCreate(['property_id'=>$p->id,'name'=>$name],['days_per_year'=>$days,'is_paid'=>$paid]);foreach([['Transport Allowance','TRANSPORT','earning'],['Housing Allowance','HOUSING','earning'],['PAYE / Statutory Tax','PAYE','deduction'],['NSSF / Pension Employee','PENSION_EE','deduction'],['NSSF / Pension Employer','PENSION_ER','employer_cost']] as [$name,$code,$type])PayrollComponent::firstOrCreate(['property_id'=>$p->id,'code'=>$code],['name'=>$name,'type'=>$type,'calculation'=>'fixed','default_value'=>0,'statutory'=>str_contains($code,'PENSION')||$code==='PAYE']);foreach([['2250','Payroll Payable','liability'],['2260','Payroll Deductions Payable','liability'],['2270','Employer Statutory Contributions Payable','liability']] as [$code,$name,$type])Account::firstOrCreate(['property_id'=>$p->id,'code'=>$code],['name'=>$name,'type'=>$type,'is_control'=>true,'is_active'=>true]);}}}